// Woobee service worker, generated by build.mjs from src/sw.js.
// Pages: network first, falling back to the last copy seen (so the installed app opens offline).
// Images, CSS, JS: cache first. The cache name changes on every deploy, which clears old copies.
const VERSION = '{{swVersion}}';
const CACHE = `woobee-${VERSION}`;
const CORE = [
  '/',
  '/shop.html',
  '/about.html',
  '/journal.html',
  '/404.html',
  '/styles.css?v={{cssVersion}}',
  '/main.js?v={{jsVersion}}',
  '/favicon.svg',
  '/manifest.webmanifest',
];

self.addEventListener('install', (event) => {
  event.waitUntil(caches.open(CACHE).then((cache) => cache.addAll(CORE)).then(() => self.skipWaiting()));
});

self.addEventListener('activate', (event) => {
  event.waitUntil(
    caches.keys()
      .then((keys) => Promise.all(keys.filter((k) => k.startsWith('woobee-') && k !== CACHE).map((k) => caches.delete(k))))
      .then(() => self.clients.claim()),
  );
});

const keep = (request, response) => {
  if (response.ok) {
    const copy = response.clone();
    caches.open(CACHE).then((cache) => cache.put(request, copy));
  }
  return response;
};

self.addEventListener('fetch', (event) => {
  const { request } = event;
  const url = new URL(request.url);
  if (request.method !== 'GET' || url.origin !== self.location.origin) return;
  // Let the film stream normally (range requests don't cache well)
  if (request.headers.has('range') || url.pathname.endsWith('.mp4')) return;

  if (request.mode === 'navigate') {
    event.respondWith(
      fetch(request)
        .then((response) => keep(request, response))
        .catch(() => caches.match(request, { ignoreSearch: true }).then((hit) => hit || caches.match('/'))),
    );
    return;
  }

  event.respondWith(caches.match(request).then((hit) => hit || fetch(request).then((response) => keep(request, response))));
});
